1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <link rel="icon" href="data:,">
11	
12	  <style>
13	    :root {
14	      --circle-hue: #8ec5ff;
15	      --circle-core: #4a7dd9;
16	      --circle-shadow: #1f3a75;
17	      --cycle: 2.5s;
18	    }
19	    * {
20	      margin: 0;
21	      padding: 0;
22	      box-sizing: border-box;
23	    }
24	    body {
25	      width: 100vw;
26	      height: 100vh;
27	      height: 100dvh;
28	      display: flex;
29	      flex-direction: column;
30	      justify-content: center;
31	      align-items: center;
32	      gap: 24px;
33	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
34	      overflow: hidden;
35	    }
36	    svg {
37	      width: min(400px, 80vmin);
38	      height: min(400px, 80vmin);
39	      overflow: visible;
40	      cursor: pointer;
41	      user-select: none;
42	      -webkit-tap-highlight-color: transparent;
43	      transition: filter 0.3s ease;
44	    }
45	    .circle-btn:hover svg {
46	      filter: brightness(1.08);
47	    }
48	    .ambient {
49	      fill: var(--circle-hue);
50	      opacity: 0.12;
51	      filter: blur(30px);
52	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
53	      transform-origin: 200px 200px;
54	      will-change: transform, opacity;
55	    }
56	    .core {
57	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
58	      transform-origin: 200px 200px;
59	      filter: url(#glow);
60	      will-change: transform, opacity;
61	    }
62	    .highlight {
63	      fill: url(#highlightGradient);
64	      transform-origin: 200px 200px;
65	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
66	      pointer-events: none;
67	      will-change: transform, opacity;
68	    }
69	    .ring {
70	      fill: none;
71	      stroke: var(--circle-hue);
72	      stroke-width: 2.5;
73	      transform-origin: 200px 200px;
74	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
75	      will-change: transform, opacity, stroke-width;
76	    }
77	    .ring--delay-1 {
78	      animation-delay: calc(var(--cycle) / 3);
79	    }
80	    .ring--delay-2 {
81	      animation-delay: calc(var(--cycle) / 3 * 2);
82	    }
83	    @keyframes pulse {
84	      0%, 100% {
85	        transform: scale(1);
86	        opacity: 0.9;
87	      }
88	      50% {
89	        transform: scale(1.05);
90	        opacity: 1;
91	      }
92	    }
93	    @keyframes breathe {
94	      0%, 100% {
95	        transform: scale(0.95);
96	        opacity: 0.1;
97	      }
98	      50% {
99	        transform: scale(1.1);
100	        opacity: 0.18;
101	      }
102	    }
103	    @keyframes ripple {
104	      0% {
105	        transform: scale(1);
106	        opacity: 0.6;
107	        stroke-width: 2.5;
108	      }
109	      100% {
110	        transform: scale(1.35);
111	        opacity: 0;
112	        stroke-width: 0.5;
113	      }
114	    }
115	    body.paused .core,
116	    body.paused .ring,
117	    body.paused .ambient,
118	    body.paused .highlight {
119	      animation-play-state: paused;
120	    }
121	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
122	       once JS is ready, control defers entirely to body.paused so the user
123	       can still explicitly resume even with reduced motion preferred. */
124	    @media (prefers-reduced-motion: reduce) {
125	      body:not(.js-ready) .core,
126	      body:not(.js-ready) .ring,
127	      body:not(.js-ready) .ambient,
128	      body:not(.js-ready) .highlight {
129	        animation-play-state: paused;
130	      }
131	    }
132	    .speed-label {
133	      color: var(--circle-hue);
134	      font-family: system-ui, sans-serif;
135	      font-size: 0.85rem;
136	      letter-spacing: 0.05em;
137	      opacity: 0.85;
138	      user-select: none;
139	      text-align: center;
140	    }
141	    .hint {
142	      display: block;
143	      margin-top: 4px;
144	      font-size: 0.7rem;
145	      opacity: 1;
146	    }
147	    .controls {
148	      display: flex;
149	      align-items: center;
150	      gap: 12px;
151	      max-width: min(320px, 90vw);
152	    }
153	    .pause-btn {
154	      display: inline-flex;
155	      align-items: center;
156	      justify-content: center;
157	      width: 36px;
158	      height: 36px;
159	      padding: 0;
160	      border-radius: 50%;
161	      border: 1px solid var(--circle-hue);
162	      background: transparent;
163	      color: var(--circle-hue);
164	      cursor: pointer;
165	      touch-action: manipulation;
166	      transition: background 0.2s ease;
167	    }
168	    .pause-btn:hover {
169	      background: rgba(142, 197, 255, 0.15);
170	    }
171	    .pause-btn:focus-visible {
172	      outline: 2px solid var(--circle-hue);
173	      outline-offset: 2px;
174	    }
175	    @media (prefers-contrast: more) {
176	      .pause-btn {
177	        border-width: 2px;
178	      }
179	      .ring {
180	        stroke-width: 3.5;
181	      }
182	    }
183	    .pause-btn svg {
184	      width: 14px;
185	      height: 14px;
186	    }
187	    .circle-btn {
188	      display: inline-flex;
189	      padding: 0;
190	      border: none;
191	      background: none;
192	      cursor: pointer;
193	      touch-action: manipulation;
194	      -webkit-tap-highlight-color: transparent;
195	      border-radius: 50%;
196	    }
197	    .circle-btn:focus-visible {
198	      outline: none;
199	    }
200	    .circle-btn:focus-visible svg {
201	      outline: 2px solid var(--circle-hue);
202	      outline-offset: 8px;
203	      border-radius: 50%;
204	    }
205	    .no-js .controls {
206	      display: none;
207	    }
208	    .no-js .circle-btn {
209	      cursor: default;
210	    }
211	  </style>
212	</head>
213	<body class="no-js">
214	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation" aria-describedby="speedText" title="Click to change pulse speed">
215	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
216	    <defs>
217	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
218	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
219	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
220	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
221	      </radialGradient>
222	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
223	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
224	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
225	      </radialGradient>
226	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
227	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
228	        <feColorMatrix in="blur" type="matrix"
229	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
230	        <feMerge>
231	          <feMergeNode in="tintedBlur"/>
232	          <feMergeNode in="SourceGraphic"/>
233	        </feMerge>
234	      </filter>
235	    </defs>
236	    <circle class="ambient" cx="200" cy="200" r="160"/>
237	    <circle class="ring" cx="200" cy="200" r="140"/>
238	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
239	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
240	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
241	    <circle class="highlight" cx="200" cy="200" r="140"/>
242	  </svg>
243	  </button>
244	  <div class="controls">
245	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
246	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
247	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
248	      </svg>
249	    </button>
250	    <p class="speed-label" id="speedLabel">
251	      <span id="speedText" aria-live="polite">Normal speed</span>
252	      <span class="hint" aria-hidden="true">Click circle to change speed</span>
253	    </p>
254	  </div>
255	  <script>
256	    const circleBtn = document.getElementById('circleBtn');
257	    const speedText = document.getElementById('speedText');
258	    const pauseBtn = document.getElementById('pauseBtn');
259	    const pauseIcon = document.getElementById('pauseIcon');
260	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
261	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
262	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
263	    const speeds = [
264	      { value: '2.5s', name: 'Normal speed' },
265	      { value: '1.2s', name: 'Fast speed' },
266	      { value: '4.5s', name: 'Slow speed' },
267	    ];
268	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
269	    let speedIndex = 0;
270	    let manuallyPaused = reducedMotionQuery.matches;
271	    // Once the user has explicitly toggled pause/play, respect that choice
272	    // instead of letting a later OS-level reduced-motion change override it.
273	    let userHasChosen = false;
274	
275	    const STORAGE_KEY = 'pulsing-circle-prefs';
276	    try {
277	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
278	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
279	        speedIndex = saved.speedIndex;
280	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
281	      }
282	      if (saved && typeof saved.manuallyPaused === 'boolean') {
283	        manuallyPaused = saved.manuallyPaused;
284	        userHasChosen = true;
285	      }
286	    } catch {
287	      // Ignore malformed or inaccessible storage; fall back to defaults.
288	    }
289	
290	    function savePrefs() {
291	      try {
292	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
293	      } catch {
294	        // Storage may be unavailable (e.g. private browsing); ignore.
295	      }
296	    }
297	
298	    function updateLabels() {
299	      const { name } = speeds[speedIndex];
300	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
301	    }
302	
303	    function cycleSpeed() {
304	      speedIndex = (speedIndex + 1) % speeds.length;
305	      const { value } = speeds[speedIndex];
306	      circleBtn.style.setProperty('--cycle', value);
307	      // Restart animations from the beginning so the new speed feels immediate
308	      // instead of jumping mid-cycle.
309	      animatedEls.forEach((el) => {
310	        el.style.animation = 'none';
311	        void el.offsetWidth;
312	        el.style.animation = '';
313	      });
314	      updateLabels();
315	      savePrefs();
316	    }
317	
318	    function applyPauseState() {
319	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
320	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
321	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
322	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
323	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
324	      updateLabels();
325	    }
326	
327	    function togglePause() {
328	      manuallyPaused = !manuallyPaused;
329	      userHasChosen = true;
330	      applyPauseState();
331	      savePrefs();
332	    }
333	
334	    circleBtn.addEventListener('click', cycleSpeed);
335	    pauseBtn.addEventListener('click', togglePause);
336	
337	    document.addEventListener('visibilitychange', applyPauseState);
338	
339	    reducedMotionQuery.addEventListener('change', (e) => {
340	      if (userHasChosen) return;
341	      manuallyPaused = e.matches;
342	      applyPauseState();
343	    });
344	
345	    // Keep multiple open tabs/windows of this page in sync with each other.
346	    window.addEventListener('storage', (e) => {
347	      if (e.key !== STORAGE_KEY || !e.newValue) return;
348	      try {
349	        const saved = JSON.parse(e.newValue);
350	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
351	          speedIndex = saved.speedIndex;
352	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
353	        }
354	        if (typeof saved.manuallyPaused === 'boolean') {
355	          manuallyPaused = saved.manuallyPaused;
356	          userHasChosen = true;
357	        }
358	        applyPauseState();
359	      } catch {
360	        // Ignore malformed storage updates from other tabs.
361	      }
362	    });
363	
364	    applyPauseState();
365	    updateLabels();
366	    circleBtn.setAttribute('aria-label', 'Pulsing blue circle animation. Click to change pulse speed.');
367	    document.body.classList.add('js-ready');
368	    document.body.classList.remove('no-js');
369	  </script>
370	</body>
371	</html>
